    static let primaryPress = Color(hex: 0x7C3AED)
    static let gradientStart = Color(hex: 0x7C3AED)
    static let gradientEnd = Color(hex: 0xA855F7)
    static let accentLight = Color(hex: 0xC4B5FD)
    static let deepViolet = Color(hex: 0x5B21B6)
    static let orbLight = Color(hex: 0x9F67FA)

    static let background = Color("Background")
    static let surface = Color("Surface")
    static let surfaceElevated = Color("SurfaceElevated")
    static let surfaceHigh = Color("SurfaceHigh")
    static let surfaceVariant = Color("SurfaceVariant")
    static let onSurfaceVariant = Color("OnSurfaceVariant")
    static let textPrimary = Color("TextPrimary")
    static let textSecondary = Color("TextSecondary")
    static let textMuted = Color("TextMuted")
    static let border = Color("Border")
    static let borderStrong = Color("BorderStrong")
    static let outline = Color("Outline")
    static let outlineVariant = Color("OutlineVariant")
    static let divider = Color("Divider")
    static let inputBorder = Color("InputBorder")
    static let primaryContainer = Color("PrimaryContainer")
    static let onPrimaryContainer = Color("OnPrimaryContainer")
    static let primaryMuted = Color("PrimaryMuted")
    static let chipSelected = Color("ChipSelected")
    static let secondary = Color("Secondary")
    static let success = Color("Success")
    static let successContainer = Color("SuccessContainer")
    static let onSuccessContainer = Color("OnSuccessContainer")
    static let warning = Color("Warning")
    static let warningContainer = Color("WarningContainer")
    static let onWarningContainer = Color("OnWarningContainer")
    static let danger = Color("Danger")
    static let dangerContainer = Color("DangerContainer")
    static let onDangerContainer = Color("OnDangerContainer")
    static let info = Color("Info")
    static let infoContainer = Color("InfoContainer")
    static let disabledBackground = Color("DisabledBackground")
    static let disabledText = Color("DisabledText")
    static let onSuccessButton = Color("OnSuccessButton")
    static let bubbleBot = Color("BubbleBot")
    static let bubbleCustomer = Color("BubbleCustomer")
    static let ringTrack = Color("RingTrack")
    static let authTop = Color("AuthTop")
    static let authMid = Color("AuthMid")
    static let authBottom = Color("AuthBottom")
    static let authCard = Color("AuthCard")
    static let authField = Color("AuthField")
    static let authFieldRing = Color("AuthFieldRing")
    static let authTitle = Color("AuthTitle")

    /// CTA_GRADIENT = [#7C3AED, #A855F7].
    static let cta = LinearGradient(colors: [gradientStart, gradientEnd], startPoint: .topLeading, endPoint: .bottomTrailing)
