    static let brandTile = LinearGradient(colors: [deepViolet, gradientStart, gradientEnd], startPoint: .topLeading, endPoint: .bottomTrailing)
    static let orbIdle = LinearGradient(colors: [deepViolet, gradientStart, orbLight], startPoint: .topLeading, endPoint: .bottomTrailing)

    /// Map trip colours cycle (§6 Maps).
    static let tripColors: [Color] = [0x2563EB, 0x16A34A, 0xF97316, 0xDB2777, 0x0891B2, 0xA16207, 0xDC2626, 0x4F46E5].map { Color(hex: $0) }
    static let tripColorHex: [UInt32] = [0x2563EB, 0x16A34A, 0xF97316, 0xDB2777, 0x0891B2, 0xA16207, 0xDC2626, 0x4F46E5]
}

enum Radius {
    static let card: CGFloat = 24
    static let control: CGFloat = 14
    static let bubble: CGFloat = 22
    static let input: CGFloat = 12
    static let authField: CGFloat = 16
    static let sheet: CGFloat = 28
    static let solidCard: CGFloat = 20
}

enum Spacing {
    static let s1: CGFloat = 4, s2: CGFloat = 8, s3: CGFloat = 12, s4: CGFloat = 16, s5: CGFloat = 20
    static let s6: CGFloat = 24, s7: CGFloat = 28, s8: CGFloat = 32, s9: CGFloat = 40, s10: CGFloat = 48
    static let gutter: CGFloat = 20
}

extension Color {
    init(hex: UInt32, opacity: Double = 1) {
        self.init(.sRGB,
                  red: Double((hex >> 16) & 0xFF) / 255,
                  green: Double((hex >> 8) & 0xFF) / 255,
                  blue: Double(hex & 0xFF) / 255,
                  opacity: opacity)
    }
}

/// AppText variants (size / line height / weight) from the parity map; sizes scale with Dynamic Type.
enum AppTextStyle {
    case display, h1, h2, title, body, bodyStrong, label, caption, tab

    var size: CGFloat {
        switch self {
        case .display: 28
        case .h1: 22
        case .h2: 18
        case .title: 16
        case .body, .bodyStrong: 15
        case .label: 13
        case .caption: 12
        case .tab: 11
        }
    }

    var lineHeight: CGFloat {
        switch self {
        case .display: 34
        case .h1: 28
        case .h2: 24
        case .title: 22
        case .body, .bodyStrong: 22
        case .label: 18
        case .caption: 16
        case .tab: 14
        }
    }

    var weight: Font.Weight {
        switch self {
        case .display, .h1: .bold
        case .h2, .title, .bodyStrong: .semibold
        case .label, .tab: .medium
        case .body, .caption: .regular
        }
    }

    var tracking: CGFloat {
        switch self {
        case .display: -0.3
        case .h1: -0.2
        default: 0
        }
    }

    var relativeTo: Font.TextStyle {
        switch self {
        case .display: .largeTitle
        case .h1: .title2
        case .h2: .title3
        case .title: .headline
        case .body, .bodyStrong: .body
        case .label: .subheadline
        case .caption, .tab: .caption
        }
    }
}

private struct AppTextModifier: ViewModifier {
    let style: AppTextStyle
    @ScaledMetric private var size: CGFloat

    init(style: AppTextStyle) {
        self.style = style
        _size = ScaledMetric(wrappedValue: style.size, relativeTo: style.relativeTo)
    }

    func body(content: Content) -> some View {
        content
            .font(.system(size: size, weight: style.weight))
            .tracking(style.tracking)
            .lineSpacing(max(0, style.lineHeight - style.size * 1.2))
    }
}

extension View {
    /// Applies one of the parity-map text styles, scaled with Dynamic Type.
    func appText(_ style: AppTextStyle) -> some View { modifier(AppTextModifier(style: style)) }

    /// Solid content card (HIG: content stays solid, glass is for controls).
    func surfaceCard(radius: CGFloat = Radius.card, padding: CGFloat = Spacing.s4, shadow: Bool = true) -> some View {
        self
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(padding)
            .background(Palette.surfaceElevated, in: RoundedRectangle(cornerRadius: radius, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous).strokeBorder(Palette.border, lineWidth: 1))
            .shadow(color: .black.opacity(shadow ? 0.12 : 0), radius: shadow ? 10 : 0, y: shadow ? 4 : 0)
    }
}
